#!/usr/bin/env python3
# r165 reviewer-authored control C6: exact toy test of the quotient-stable contraction descent lemma
# in a genuine quotient (node-3 seed ideal present BELOW the source level), with the independent model.
#   seeds: (ad e3)^(1+r) e1 ~ (ad v)^r u1 at level r+1, (ad e3)^(1+s) e2 ~ (ad v)^s u2 at level s+1;
#   I = ideal of L(M) generated by their l-modules;  S_n = L_n/I_n.
# For every level-n type: P (free lowest), N = P cap I_n, det(Omega|P) != 0 ?, and injectivity of the
# ACTUAL D3 : P/N -> L_{n-1}/I_{n-1}.  The lemma predicts: det != 0  ==>  actual injective.
# Also checks Omega(N) <= N, D3(I_n) <= I_{n-1}, F_j(seed) = 0.  Exact Fraction arithmetic throughout.
import sys
sys.dont_write_bytecode = True
import json, hashlib, importlib.util, os
from fractions import Fraction as Fr

HERE = os.path.dirname(os.path.abspath(__file__))
spec = importlib.util.spec_from_file_location('r165model', os.path.join(HERE, 'r165-c2-omega-model.py'))
K = importlib.util.module_from_spec(spec); spec.loader.exec_module(K)

def degree(code, n):
    ls = K.letters(code, n)
    return (sum(K.LET[t][0] for t in ls), sum(K.LET[t][1] for t in ls))

_LB = {}
def lb(n, a, b):
    if (n, a, b) not in _LB:
        _LB[(n, a, b)] = K.lyndon_basis(n, a, b)[1]
    return _LB[(n, a, b)]

def lie_vec(x, n, a, b):
    lw = lb(n, a, b)
    co, rem = K.lie_coordinates(x, n, lw)
    assert not rem, 'not a Lie element'
    return [Fr(co.get(w, 0)) for w in lw]

class Span:
    """Exact row-echelon span of Fraction vectors."""
    def __init__(self, dim):
        self.dim, self.rows, self.piv = dim, [], []
    def reduce(self, v):
        v = list(v)
        for row, p in zip(self.rows, self.piv):
            if v[p] != 0:
                f = v[p]
                v = [x - f * y for x, y in zip(v, row)]
        return v
    def add(self, v):
        v = self.reduce(v)
        p = next((i for i, x in enumerate(v) if x != 0), None)
        if p is None:
            return False
        pv = v[p]
        v = [x / pv for x in v]
        # keep fully reduced
        new_rows = []
        for row in self.rows:
            if row[p] != 0:
                f = row[p]
                row = [x - f * y for x, y in zip(row, v)]
            new_rows.append(row)
        self.rows = new_rows + [v]
        self.piv = self.piv + [p]
        return True
    def contains(self, v):
        return all(x == 0 for x in self.reduce(v))
    def rank(self):
        return len(self.rows)

def vec_to_dict(v, n, a, b):
    lw = lb(n, a, b)
    den = 1
    for q in v:
        den = den * q.denominator // __import__('math').gcd(den, q.denominator)
    x = {}
    for coef, w in zip(v, lw):
        if coef:
            for key, val in K.expand(tuple(K.letters(w, n))).items():
                x[key] = x.get(key, 0) + int(coef * den) * val
    return {k: c for k, c in x.items() if c}

def split_by_degree(x, n):
    parts = {}
    for code, c in x.items():
        parts.setdefault(degree(code, n), {})[code] = c
    return parts

def seed(letter, k):
    x, n = {letter: 1}, 1
    for _ in range(k):
        x = K.bracket_dict({0: 1}, 1, x, n); n += 1
    return x, n

def ideal(r, s, nmax):
    """I[n][(a,b)] = Span of Lie-coordinate vectors (exact)."""
    I = {}
    seeds = []
    for letter, par in ((1, r), (2, s)):
        if par + 1 <= nmax:
            seeds.append(seed(letter, par))
    for n in range(1, nmax + 1):
        I[n] = {}
        gens = []
        for (x, nl) in seeds:
            if nl == n:
                # l-module generated by the lowest vector x: closure under 2e1, 2e2
                frontier = [x]
                while frontier:
                    nxt = []
                    for y in frontier:
                        for (dg, part) in split_by_degree(y, n).items():
                            sp = I[n].setdefault(dg, Span(len(lb(n, *dg))))
                            if sp.add(lie_vec(part, n, *dg)):
                                for cols in (K.RHO_E1, K.RHO_E2):
                                    z = K.der_dict(cols, part, n)
                                    if z:
                                        nxt.append(z)
                    frontier = nxt
        if n >= 2 and (n - 1) in I:
            for dg, sp in I[n - 1].items():
                for row in sp.rows:
                    y = vec_to_dict(row, n - 1, *dg)
                    for k in range(8):
                        z = K.bracket_dict({k: 1}, 1, y, n - 1)
                        for (dg2, part) in split_by_degree(z, n).items():
                            sp2 = I[n].setdefault(dg2, Span(len(lb(n, *dg2))))
                            sp2.add(lie_vec(part, n, *dg2))
    return I, seeds

def lowest_basis(n, a, b):
    lw = lb(n, a, b)
    rows = []
    for cols, (da, db) in ((K.RHO_F1, (1, 0)), (K.RHO_F2, (0, 1))):
        if a - da < 0 or b - db < 0:
            continue
        tl = lb(n, a - da, b - db)
        M = [[Fr(0)] * len(lw) for _ in tl]
        for j, w in enumerate(lw):
            img = K.der_dict(cols, K.expand(tuple(K.letters(w, n))), n)
            if img:
                v = lie_vec(img, n, a - da, b - db)
                for i in range(len(tl)):
                    M[i][j] = v[i]
        rows.extend(M)
    sp = Span(len(lw))
    for row in rows:
        sp.add(row)
    piv = set(sp.piv)
    free = [c for c in range(len(lw)) if c not in piv]
    basis = []
    for fcol in free:
        v = [Fr(0)] * len(lw)
        v[fcol] = Fr(1)
        for row, p in zip(sp.rows, sp.piv):
            v[p] = -row[fcol]
        basis.append(v)
    return basis, free

def det_exact(M):
    M = [list(r) for r in M]
    n = len(M)
    d = Fr(1)
    for c in range(n):
        p = next((i for i in range(c, n) if M[i][c] != 0), None)
        if p is None:
            return Fr(0)
        if p != c:
            M[c], M[p] = M[p], M[c]; d = -d
        d *= M[c][c]
        for i in range(c + 1, n):
            if M[i][c] != 0:
                f = M[i][c] / M[c][c]
                M[i] = [x - f * y for x, y in zip(M[i], M[c])]
    return d

def omega_dict(x, n, r, s):
    res = {}
    for (i, j), kw in K.KW.items():
        Fx = K.F_numeric(j, x, n, r, s)
        res = K.add_dicts((1, res), (kw, K.bracket_dict({i: 1}, 1, Fx, n - 1)))
    return res

def run(r, s, n):
    I, seeds = ideal(r, s, n)
    out = {'r': r, 's': s, 'level': n, 'types': []}
    seed_kill = True
    for (x, nl) in seeds:
        for j in range(8):
            if K.F_numeric(j, x, nl, r, s):
                seed_kill = False
    out['all_F_j_kill_seeds'] = seed_kill
    d3_ideal_ok = True
    for dg, sp in I.get(n, {}).items():
        for row in sp.rows:
            y = vec_to_dict(row, n, *dg)
            z = K.F_numeric(0, y, n, r, s)
            if z:
                tsp = I[n - 1].get(dg)
                if tsp is None or not tsp.contains(lie_vec(z, n - 1, *dg)):
                    d3_ideal_ok = False
    out['D3_maps_I_n_into_I_(n-1)'] = d3_ideal_ok
    degs = sorted({(a, b) for a in range(0, 2 * n + 1) for b in range(0, 2 * n + 1)
                   if (2 * a - b - n) <= 0 and (-a + 2 * b - n) <= 0 and lb(n, a, b)})
    for (a, b) in degs:
        Pb, freecols = lowest_basis(n, a, b)
        m = len(Pb)
        if m == 0:
            continue
        isp = I[n].get((a, b))
        # N = P cap I_n, and Omega(I_n) <= I_n at this degree (=> Omega(N) <= N since Omega(P) <= P)
        omega_preserves_I = True
        if isp is None:
            dimN = 0
        else:
            tot = Span(len(lb(n, a, b)))
            for row in isp.rows:
                tot.add(row)
            dimI = tot.rank()
            for v in Pb:
                tot.add(v)
            dimN = m + dimI - tot.rank()
            for row in isp.rows:
                y = vec_to_dict(row, n, a, b)
                oy = omega_dict(y, n, r, s)
                if oy and not isp.contains(lie_vec(oy, n, a, b)):
                    omega_preserves_I = False
        # Omega on P (exact matrix in basis Pb) and its determinant
        Pspan = Span(len(lb(n, a, b)))
        for v in Pb:
            Pspan.add(v)
        lw = lb(n, a, b)
        Om = []
        for v in Pb:
            x = vec_to_dict(v, n, a, b)
            ox = omega_dict(x, n, r, s)
            ov = lie_vec(ox, n, a, b) if ox else [Fr(0)] * len(lw)
            # scale back: vec_to_dict multiplied by lcm of denominators
            from math import gcd
            L = 1
            for q in v:
                L = L * q.denominator // gcd(L, q.denominator)
            ov = [q / L for q in ov]
            assert Pspan.contains(ov), 'Omega does not preserve P'
            Om.append([ov[c] for c in freecols])
        Mt = [[Om[j][i] for j in range(m)] for i in range(m)]
        dOm = det_exact(Mt)
        # actual D3 : P/N -> L_{n-1}/I_{n-1}; also the free D3 rank on P for comparison
        tl = lb(n - 1, a, b)
        rank_actual, rank_free = 0, 0
        if tl:
            img = Span(len(tl))
            free_img = Span(len(tl))
            tsp = I[n - 1].get((a, b))
            if tsp is not None:
                for row in tsp.rows:
                    img.add(row)
            base = img.rank()
            for v in Pb:
                x = vec_to_dict(v, n, a, b)
                z = K.F_numeric(0, x, n, r, s)
                if z:
                    zz = lie_vec(z, n - 1, a, b)
                    img.add(zz)
                    free_img.add(zz)
            rank_actual = img.rank() - base
            rank_free = free_img.rank()
        injective = rank_actual == m - dimN
        out['types'].append({'a': a, 'b': b, 'dimP_free': m, 'dimN_P_cap_I': dimN, 'dim_actual_source': m - dimN,
                             'omega_preserves_I_n_at_degree': omega_preserves_I,
                             'det_Omega_nonzero': dOm != 0, 'free_D3_rank': rank_free,
                             'actual_D3_rank': rank_actual, 'actual_D3_injective': injective,
                             'lemma_prediction_respected': (dOm == 0) or injective})
    return out

if __name__ == '__main__':
    res = {'start_clock': K.clock(),
           'script_sha256': hashlib.sha256(open(__file__, 'rb').read()).hexdigest(),
           'model_sha256': hashlib.sha256(open(os.path.join(HERE, 'r165-c2-omega-model.py'), 'rb').read()).hexdigest(),
           'runs': []}
    for (r, s, n) in [(2, 9, 4), (1, 9, 3), (1, 9, 4), (2, 2, 4), (1, 2, 4)]:
        res['runs'].append(run(r, s, n))
        print(f'done {(r, s, n)} {K.clock()}', file=sys.stderr, flush=True)
    res['lemma_violations'] = sum(1 for R in res['runs'] for t in R['types'] if not t['lemma_prediction_respected'])
    res['cases_with_nonzero_N_and_nonzero_det'] = sum(1 for R in res['runs'] for t in R['types']
                                                     if t['dimN_P_cap_I'] > 0 and t['det_Omega_nonzero'])
    res['end_clock'] = K.clock()
    print(json.dumps(res, indent=1))
